"""Money values stored as integer minor units (cents)."""

from __future__ import annotations


class Money:
    """An amount of one currency in minor units, for example 1250 USD cents."""

    def __init__(self, cents: int, currency: str) -> None:
        self.cents = cents
        self.currency = currency

    def __eq__(self, other: object) -> bool:
        return isinstance(other, Money) and (self.cents, self.currency) == (other.cents, other.currency)

    def __repr__(self) -> str:
        return f"Money({self.cents}, {self.currency!r})"

    def add(self, other: Money) -> Money:
        """Sum of two amounts in the same currency."""
        self._check(other)
        return Money(self.cents + other.cents, self.currency)

    def subtract(self, other: Money) -> Money:
        """Difference of two amounts in the same currency."""
        self._check(other)
        return Money(self.cents - other.cents, self.currency)

    def __add__(self, other: Money) -> Money:
        return self.add(other)

    def __sub__(self, other: Money) -> Money:
        return self.subtract(other)

    def multiply(self, factor: float) -> Money:
        """Scale by factor, rounding half to even at the cent."""
        return Money(round(self.cents * factor), self.currency)

    def split(self, parts: int) -> list[Money]:
        """Split into parts that differ by at most one cent and add up exactly."""
        base, extra = divmod(self.cents, parts)
        return [Money(base + (1 if i < extra else 0), self.currency) for i in range(parts)]

    def is_zero(self) -> bool:
        """True when the amount is zero."""
        return self.cents == 0

    def _check(self, other: Money) -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

